"""由负责电商售后、仓储物流的 agent 独立创作；仅辅助序列化与校验。"""
import json
import subprocess
import sys
from pathlib import Path
from openjev.data import write_jsonl, CASE_TYPES

ROOT = Path(__file__).resolve().parents[2]
TOPICS = {}

def c(state, instruction, options, probs, evidence):
    criteria = dict(options)
    return state, {'type':'choice','instructions':instruction,'criteria':criteria}, {'probabilities':dict(zip(criteria,probs))}, evidence

def s(state, instruction, levels, probs, evidence):
    return state, {'type':'score','instructions':instruction,'criteria':levels}, {'probabilities':{str(i):p for i,p in enumerate(probs)}}, evidence

def n(state, instruction, yes, evidence):
    return state, {'type':'noul','instructions':instruction}, {'noul':yes}, evidence

def m(state, cq, sq, nq):
    return (state, {'分类':cq[1], '程度':sq[1], '核实':nq[1]}, {'分类':cq[2], '程度':sq[2], '核实':nq[2]}, {'分类':cq[3], '程度':sq[3], '核实':nq[3]})

def save(topic, cases):
    assert len(cases)==10
    rows=[]
    for slot, (state, question, label, evidence) in enumerate(cases,1):
        mixed=slot==10
        rows.append({'sample_id':f'{topic}-{slot:02d}','topic_id':topic,'slot':slot,
          'request':{'model':'jev-latest','state':state,'questions':question if mixed else {'判断':question}},
          'labels':label if mixed else {'判断':label},
          'review':{'case_type':CASE_TYPES[slot],'evidence':evidence if mixed else {'判断':evidence},'label_source':'agent_synthetic'}})
    destination=ROOT/'data/drafts'/f'{topic}.jsonl'
    if destination.exists() or (ROOT/'data/shards'/f'{topic}.jsonl').exists():
        raise FileExistsError(topic)
    write_jsonl(destination,rows)
    subprocess.run([sys.executable,'-m','scripts.finalize_shard',str(destination)],cwd=ROOT,check=True)

