cold_long={
'货运批次':'CL-20260919-008412','判定范围':'仅判断本批货物实际温控区内的有效温度记录，不评价包装、交接文书或收货人情绪。下文全部为该批的核查案卷，不依赖外部温控标准。',
'适用规则':{'允许温区':'2—8℃，包含边界','偏离定义':'箱内有效探头任一连续超过上限或低于下限满5分钟，判发生偏离','有效位置':'探头位于封闭货物箱内部；被取出后的空气读数不属于货温','完整性':'须核对探头身份、位置、校准与时间连续性，缺项不能直接认定合格'},
'记录':[
{'编号':'TEMP-20260919-001','来源':'受理单','内容':'托运批次008412由十二个保冷箱组成，全部装在同一车厢。客户要求按本单明确的2至8℃规则核查，不使用其他货品的标准。报案原因是收货界面出现12℃红色提示，需确认该提示是否来自仍位于货物中的探头。'},
{'编号':'TEMP-20260919-002','来源':'设备清单','内容':'本批使用主记录仪IN-A、备用记录仪IN-B与演示显示器OUT-D。IN-A和IN-B用于箱内监测，OUT-D只显示调度台环境温度，不随车。编号标签和封装照片均已保存，不能把名称里包含温度的设备都当作货物探头。'},
{'编号':'TEMP-20260919-003','来源':'校准报告甲','内容':'IN-A发运前用三个参考点核验，报告显示读数偏差在本任务允许范围内，校准有效期覆盖当天。报告写明出厂编号与现场标签一致，不是同型号另一台仪器的报告，核查人员已比对二维码。'},
{'编号':'TEMP-20260919-004','来源':'校准报告乙','内容':'IN-B同样完成发运前校验，有效期覆盖全程。曾经校准失效的是仓库另一台IN-C，这台没有装入本批。客服旧文件夹里同时保存两份报告，复核时按设备号剔除了不属于本批的失效报告。'},
{'编号':'TEMP-20260919-005','来源':'装箱设计','内容':'每箱的温度由箱内记录节点采集并汇入主备仪器，节点编号B01至B12与箱号一一对应。显示器上单独的环境通道没有对应箱号。核查范围包含十二个货箱，不能只查看平均值，也不能遗漏读数最高的一箱。'},
{'编号':'TEMP-20260919-006','来源':'装箱照片','内容':'发车前摄影逐箱展示节点位于货品中间、未接触冰袋或外壁，随后封箱。主备探头都在封闭箱体内，导线没有穿出箱外。每张照片同时显示箱号和节点标签，可以追溯初始位置。'},
{'编号':'TEMP-20260919-007','来源':'预冷阶段','内容':'预冷结束后十二箱有效记录在3.8至4.6℃之间，持续三十分钟稳定。工作人员等到各箱均进入范围后才开始本次运输计时；此前空箱预冷过程不承载货物，文件已单独命名避免误并进运输记录。'},
{'编号':'TEMP-20260919-008','来源':'发车交接','内容':'发车清单记载箱封完整，采样间隔每分钟一次，设备时钟统一。司机没有手动修改采样周期或暂停记录。交接单注明需要保留主备原始文件，不允许仅交一张绿色合格截屏就结束核查。'},
{'编号':'TEMP-20260919-009','来源':'第一段道路','内容':'从仓库至高速入口，B01至B12有效温度最低3.7℃、最高4.9℃，全部连续。途中停车等红灯使车速下降，但冷机正常工作；车辆停车事件本身并不是温度偏离证据，仍依据探头记录判断。'},
{'编号':'TEMP-20260919-010','来源':'主备比对','内容':'IN-A和IN-B对相同箱号的时间差不到一秒，整个首段读数相差不超过0.2℃。按本任务校验条件两套都有效，未发现主仪器漏点被备用覆盖而不记录的情况；核查表保留两套原始数值而非只取较低值。'},
{'编号':'TEMP-20260919-011','来源':'第一次休息站','内容':'车辆在休息站停留二十分钟，车厢外门打开检查绑带，但十二个保冷箱没有拆封。箱内最高温升到5.2℃后稳定，没有达到8℃上限。外门打开可以提示需关注，但不等于箱内必定超温。'},
{'编号':'TEMP-20260919-012','来源':'司机备注','内容':'司机说停车时体感很热，曾给调度发“温度上去了”的语音。追问后明确指路边气温，不是查看箱内记录得到的结论。核查中把这段主观备注保留为背景，不拿它代替数值证据或擅自推断货物受热。'},
{'编号':'TEMP-20260919-013','来源':'异常提示初查','内容':'调度显示器OUT-D在休息站时显示31℃，客服截屏把这行也圈红了。设备映射表证明该行没有箱号、属于仓库调度台环境通道。它甚至不在车上，因此不能据此断言货箱出现连续超温。'},
{'编号':'TEMP-20260919-014','来源':'续程数据','内容':'车辆继续行驶后各箱有效读数在4.1至5.0℃之间，没有因重新行车而丢采样。文件里休息站前后的时间戳连续递增，GPS短暂断网只影响位置显示，温度仪本地存储一直正常。'},
{'编号':'TEMP-20260919-015','来源':'数据上传说明','内容':'平台在隧道内未收到在线温度，界面画了一段虚线。出隧道后设备补传完整本地数据，原始序列能覆盖该时间段。虚线是传输延迟，复核已用补传序列验证，不能继续当成温度缺测。'},
{'编号':'TEMP-20260919-016','来源':'隧道原始序列','内容':'隧道持续十二分钟，十二箱每分钟都有记录，各箱范围4.0至5.3℃，设备状态正常。每条记录带不同递增时间戳和采样序号，不是平台把最后一个数机械复制十二遍，校验和也与原始导出相符。'},
{'编号':'TEMP-20260919-017','来源':'中转接收','内容':'中转站接收整车封闭箱体，没有重新装货。交接处扫描B01至B12箱号并检查封条，未发现调包。主备设备仍随原箱，防止另一批正常记录被误配到本批而掩盖异常的风险已有身份核验。'},
{'编号':'TEMP-20260919-018','来源':'中转等待','内容':'车辆等待装卸通道三十五分钟，最高箱温为B09的5.8℃、最低为B02的4.2℃。记录完整，没有超过上限。等待时间较长影响配送进度，但本题按温控规则判断，不把延误直接当作温度不合格。'},
{'编号':'TEMP-20260919-019','来源':'开箱权限','内容':'中转站拟检查B07外箱标签，操作规程允许只看箱外标签，实际视频也未拆内封。有人在群里说“检查箱子”可能被理解成开箱，值班员确认只是外观核对，箱内节点位置在此阶段没有变化。'},
{'编号':'TEMP-20260919-020','来源':'箱号更正','内容':'中转记录把B07误录成B17，而该批只有十二箱。扫码原始图和设备节点号均指B07，值班长保留修改痕迹更正。修正的是箱号书写，不是温度值；相关时间段B07数据仍为4.5至5.4℃且连续。'},
{'编号':'TEMP-20260919-021','来源':'车厢冷机重启','内容':'冷机在中转站例行切换电源，停机三分钟后恢复。十二个独立保冷箱的温度没有超过6℃，主备记录均如此。机械事件可能有风险，但给定规则不按停机本身判偏离，必须对应箱内有效温度和持续时间。'},
{'编号':'TEMP-20260919-022','来源':'第二段出发','内容':'出发时核验所有箱封仍完整，IN-A和IN-B设备电量足够，时钟未重置。调度把一条旧批次报警附在当前聊天中，核查发现其批号为008399，已标明不用于本批判定，避免跨批次串证。'},
{'编号':'TEMP-20260919-023','来源':'路程升温段','内容':'第二段经过阳光较强路段，B11从4.7℃逐步升至5.9℃后回落，其余箱未超过5.6℃。完整趋势保留在原始文件中，最高点真实但仍低于8℃，不能仅因曲线向上或颜色变化认定偏离。'},
{'编号':'TEMP-20260919-024','来源':'平台颜色规则','内容':'平台把5.5℃以上显示为橙色提醒，提醒阈值由页面个人设置决定；本批合同允许至8℃。客服核对后注明橙色不等于规则违规，最终仍用温区和连续五分钟条件，不采用界面颜色作为替代标准。'},
{'编号':'TEMP-20260919-025','来源':'传感器单位','内容':'一份下载表的温度列单位被导出器显示为华氏度，检查文件头发现数值本身已转换。核查人员重新按摄氏度导出并与设备直读对比，没有把两种单位直接混在同一序列；转换后全段仍在3至6℃之间。'},
{'编号':'TEMP-20260919-026','来源':'单位复核附件','内容':'B04对应样点在设备上读5℃，华氏导出显示41°F，两者为同一时刻同一数值的不同单位。客户圈出的41并非41℃。附件分别保留单位标题，不通过删除较高数字来制造合格记录。'},
{'编号':'TEMP-20260919-027','来源':'到站排队','内容':'到收货站后等待验收十五分钟，车辆停在遮阳棚。十二箱有效温度范围3.9至5.7℃，内封尚未打开。收货人查看外箱没有发现潮湿，但这一外观信息只作交接记录，温控结论仍由探头决定。'},
{'编号':'TEMP-20260919-028','来源':'收货人问询','内容':'收货人问“昨天别的车有超温，这车会不会一样”，客服解释需要看本车本批。案卷没有用昨天事件估算本批温度，也没有因为同一司机运过其他批次就改变设备读数。本次身份和时间范围另有明确记录。'},
{'编号':'TEMP-20260919-029','来源':'验收开始','内容':'验收台逐箱核对箱号和封条后才拆封。前六箱读取至交接完成的有效数据均完整，温度最低3.6℃最高5.8℃。收货人直接在设备上查看最大值，与主备导出一致，没有发现某箱导出文件缺少尾段。'},
{'编号':'TEMP-20260919-030','来源':'B07处理过程','内容':'第七箱拆封后先把货品搬入受控冷柜，备用节点继续放在货品旁记录，随后技术员取出主探头IN-A对应节点准备读数。取出的时刻在视频和交接表均有记录，不能把取出后的空气温度算进货物温控区。'},
{'编号':'TEMP-20260919-031','来源':'B07节点位置','内容':'取出的主节点放在验收台外侧，台面没有冷却。标签仍显示B07，因为设备名字不会因移出而自动改成环境节点。判断有效性需要结合位置事件，不能只看标签含B07就认为它之后一直贴着货物。'},
{'编号':'TEMP-20260919-032','来源':'12℃报警原点','内容':'主节点离开箱内数分钟后上升到12℃，平台产生红色报警。该时段视频明确节点在室内验收台，货品已经进入冷柜。客户投诉截图对应的就是此时此节点，报警是真实空气读数但不属于箱内货物温度。'},
{'编号':'TEMP-20260919-033','来源':'备用节点佐证','内容':'同一时段IN-B的B07节点仍在货品中间，记录为4.8至5.3℃，每分钟都有数据且校准有效。这使B07在移交冷柜过程中也有连续有效覆盖，不是简单删掉12℃以后留下一个无法判断的空白时段。'},
{'编号':'TEMP-20260919-034','来源':'移交时点划分','内容':'本批责任记录截至货品进入收货冷柜并完成交接，B07的取出主节点事件发生在货品入柜之后。即使把额外五分钟交接等待也纳入检查，备用节点仍完整且在允许区间，没有以提前结束统计掩盖未测部分。'},
{'编号':'TEMP-20260919-035','来源':'视频时间核验','内容':'验收视频时钟比记录仪快两分钟，技术员用同框报时事件校正，两套时间线可以对应。校正后主节点达到12℃仍发生在取出之后，未出现先超温后移出再掩饰的逆序问题，原始视频没有剪断。'},
{'编号':'TEMP-20260919-036','来源':'主节点移出前','内容':'复核取出前最后十分钟，B07主节点最高5.6℃，备用最高5.5℃。两条曲线直到取出时都相近，之后主节点才向环境温度上升。这个分叉与位置变化一致，支持将后段标为空气而不是随意挑选较低的一条。'},
{'编号':'TEMP-20260919-037','来源':'后五箱验收','内容':'B08至B12没有出现类似提前取探头操作，全部在货品入柜后结束本批记录。五箱在验收阶段最低3.8℃、最高5.9℃，节点序列完整，收货员逐箱签字确认箱号与文件匹配，不能只用B07结论代表它们。'},
{'编号':'TEMP-20260919-038','来源':'文件名纠错','内容':'工作人员曾把IN-A导出文件命名为“全程超温”，文件名是看到红色报警后的个人判断，不是原始传感器字段。复核保留文件内容与修改历史，重命名为设备号和批号，标签判断不依据这个带结论的旧文件名。'},
{'编号':'TEMP-20260919-039','来源':'连续性总检','内容':'核查员逐箱检查每分钟采样序号，发车到各箱交接完成没有缺点。B07主节点移出后由本来就在货品内的备用节点连续覆盖，两个有效区段存在时间重叠，不是把相隔几分钟的记录硬接在一起。'},
{'编号':'TEMP-20260919-040','来源':'极值总检','内容':'对所有箱内有效区段计算逐箱最低和最高值，最低为B02的3.1℃，最高为B11的5.9℃。没有任何有效样点达到或超过8℃，也没有低于2℃，所以无需以四分钟、五分钟的界线勉强解释一个真实超界片段。'},
{'编号':'TEMP-20260919-041','来源':'原始值保全','内容':'被排除的12℃及31℃环境值仍保存在附件，未从设备文件里删除。判定表增加有效位置列，写清各条记录为什么属于环境或箱内。保留异常原始值使复核能重现分类，避免只有剪裁后的“正常数据”。'},
{'编号':'TEMP-20260919-042','来源':'人工填补排查','内容':'平台导出有一个“自动补点”选项，核查人员选择关闭后重新导出，数量与仪器本地文件一致。没有用插值或前值填补温度缺口；隧道阶段的补传来自真实本地存储，序列校验通过并能对应时间戳。'},
{'编号':'TEMP-20260919-043','来源':'货品转移照片','内容':'B07货物由原保冷箱进入冷柜时，照片同时显示货号、箱号和留在货品旁的备用节点。冷柜内另有上批产品，核查用本批货号区分，没有把旁边产品的节点读取误当成本批，交接数量也与装箱数量一致。'},
{'编号':'TEMP-20260919-044','来源':'收货人复核意见','内容':'收货人同意截图中12℃来自已放在验收台上的主节点，但要求确认这不意味着货物本身必定正常。核查人员因此提交备用连续记录和位置视频；判断建立在正面有效数据上，而不只是说客户截图不能用。'},
{'编号':'TEMP-20260919-045','来源':'双方规则确认','内容':'发货方和收货方确认本题适用的上限就是8℃，没有另一个未披露的5℃要求，也不因屏幕橙色提醒改变合同温区。双方确认交接前全程数据均可读取，记录范围覆盖每个货箱，没有只挑某段天气凉时计算。'},
{'编号':'TEMP-20260919-046','来源':'责任与结论区分','内容':'验收操作把主探头拿出后仍连接显示器，容易产生误读，这个流程问题另行记录。是否应改进操作与本批温度是否实际超限是不同问题，不能因为流程有瑕疵就把明确正常的箱内有效数据标成偏离。'},
{'编号':'TEMP-20260919-047','来源':'旧客服判断修订','内容':'早期客服依据截图写“12℃持续较久，可能超温”，当时未核验位置。补齐位置和备用数据后，早期文字被标为待核猜测。保留历史是为了说明结论更新过程，而不是把两个不同时点意见同时当成有效事实。'},
{'编号':'TEMP-20260919-048','来源':'独立交叉检查','内容':'另一位核查员按设备编号、箱号、时间和位置重新匹配记录，不先读取第一位的结论。她也定位12℃段在箱外，并确认十二箱有效温区均在3.1至5.9℃、无缺测。两次检查用同一原始证据但独立建立索引。'},
{'编号':'TEMP-20260919-049','来源':'结案附件清单','内容':'保存装箱照片、两份有效校准报告、十二箱主备原始序列、隧道补传校验、验收连续视频、节点取出时刻及双方交接表。附件按本批008412索引，昨日批次和调度环境数据显示文件单列，防止后续再次串证。'},
{'编号':'TEMP-20260919-050','来源':'当前核查结果','内容':'截至交接完成，十二个货箱在所有有效箱内记录中始终位于2至8℃允许区间，记录连续。红色12℃段发生于主节点移出货物后的台面环境，B07货品同期有正常的有效备用记录。没有发现符合本批规则的温度偏离。'}
]}
